-- 595: Original BrillaPrep Cambridge IGCSE Chemistry (0620) sprint 3 beta questions, part 2 of 13 (batch igcse-chemistry-sprint3-001).
-- Curriculum-aligned practice content; not official Cambridge International, WAEC or NSMQ examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_595_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_595_guard;
INSERT INTO _migration_595_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_igcse_chem_s3_005' AND NOT (q.topic_id IS 'topic_igcse_chem_atomic' AND q.subject_id IS 'subj_igcse_chemistry' AND q.exam_type_id IS 'igcse' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Chlorine exists naturally as two isotopes, ³⁵Cl and ³⁷Cl. Answer the following questions about these isotopes.' AND q.question_type IS 'structured' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS '(a) atoms of the same element with different numbers of neutrons; (b) 17 protons, 20 neutrons, 17 electrons; (c) identical electron arrangements give identical chemical properties.' AND q.explanation IS '(a) Isotopes are atoms of the same element (same proton number) with different nucleon numbers because they contain different numbers of neutrons. (b) Chlorine has proton number 17, so every chlorine atom has 17 protons and, being neutral, 17 electrons; neutrons = 37 − 17 = 20. (c) Chemical reactions involve only the outer electrons; both isotopes have the configuration 2,8,7, so they behave identically. The extra neutrons change only the mass.' AND q.difficulty IS 'medium' AND q.points IS '4' AND q.marks IS '4' AND q.time_limit IS '300' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Define' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_cambridge')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_igcse_chem_s3_005' AND NOT (r.batch_id IS 'igcse-chemistry-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Chemistry (0620) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-chemistry-0620/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_595_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_igcse_chem_s3_006' AND NOT (q.topic_id IS 'topic_igcse_chem_periodic' AND q.subject_id IS 'subj_igcse_chemistry' AND q.exam_type_id IS 'igcse' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which statement about the elements in Group I of the Periodic Table is correct?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. They are soft metals whose reactivity increases down the group.","B. They are unreactive gases with full outer shells.","C. Their reactivity decreases down the group.","D. They form ions with a 2− charge."]' AND q.correct_answer IS 'A' AND q.explanation IS 'Group I elements are the alkali metals: soft, with one outer electron. Down the group the outer electron is lost more easily, so reactivity increases from lithium to potassium. (Full outer shells describe Group 0 noble gases; Group I atoms form 1+ ions, not 2−.) Therefore the correct answer is A: They are soft metals whose reactivity increases down the group..' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_cambridge')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_igcse_chem_s3_006' AND NOT (r.batch_id IS 'igcse-chemistry-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Chemistry (0620) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-chemistry-0620/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_595_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_igcse_chem_s3_007' AND NOT (q.topic_id IS 'topic_igcse_chem_periodic' AND q.subject_id IS 'subj_igcse_chemistry' AND q.exam_type_id IS 'igcse' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which halogen is a green gas at room temperature?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Bromine","B. Chlorine","C. Iodine","D. Astatine"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Chlorine is a green gas at room temperature. (Bromine is a red-brown liquid and iodine a grey-black solid; astatine is a dark solid at the bottom of Group VII.) Therefore the correct answer is B: Chlorine.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'State' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_cambridge')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_igcse_chem_s3_007' AND NOT (r.batch_id IS 'igcse-chemistry-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Chemistry (0620) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-chemistry-0620/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_595_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_igcse_chem_s3_008' AND NOT (q.topic_id IS 'topic_igcse_chem_periodic' AND q.subject_id IS 'subj_igcse_chemistry' AND q.exam_type_id IS 'igcse' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Elements in the same group of the Periodic Table have similar chemical properties. This is because the atoms have the same number of…' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. electron shells.","B. protons in the nucleus.","C. electrons in their outer shell.","D. neutrons in the nucleus."]' AND q.correct_answer IS 'C' AND q.explanation IS 'Chemical behaviour is governed by the outer-shell electrons, and a group collects elements with the same number of outer electrons. (Atoms in the same period share the number of shells; the proton number is unique to each element; neutron number varies even between isotopes.) Therefore the correct answer is C: electrons in their outer shell..' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'State' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_cambridge')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_igcse_chem_s3_008' AND NOT (r.batch_id IS 'igcse-chemistry-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Chemistry (0620) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-chemistry-0620/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_igcse_chem_s3_005', 'topic_igcse_chem_atomic', 'subj_igcse_chemistry', 'igcse', NULL, NULL, 'Chlorine exists naturally as two isotopes, ³⁵Cl and ³⁷Cl. Answer the following questions about these isotopes.', 'structured', NULL, NULL, '(a) atoms of the same element with different numbers of neutrons; (b) 17 protons, 20 neutrons, 17 electrons; (c) identical electron arrangements give identical chemical properties.', '(a) Isotopes are atoms of the same element (same proton number) with different nucleon numbers because they contain different numbers of neutrons. (b) Chlorine has proton number 17, so every chlorine atom has 17 protons and, being neutral, 17 electrons; neutrons = 37 − 17 = 20. (c) Chemical reactions involve only the outer electrons; both isotopes have the configuration 2,8,7, so they behave identically. The extra neutrons change only the mass.', 'medium', '4', '4', '300', NULL, NULL, '1', NULL, NULL, 'Define', 'AO1', NULL, NULL, 'board_cambridge');
